INSERT INTO periods (period_id, period_name, start_year, end_year) VALUES
 ('PER_MODERN_OCCULT','Modern Occult Revival',1850,1950)
INSERT INTO sources (source_id, source_type, title, scope) VALUES
 ('SRC_GOLDEN_DAWN','primary text','The Hermetic Order of the Golden Dawn corpus (cipher manuscripts; Regardie, The Golden Dawn)','Modern Occult')
INSERT INTO _e VALUES
 ('ENT_THL_PANTHEON','The Thelemic Pantheon','Thelemic','Collective','Collective','Thelema; the deities of Liber AL; the new aeon','B','The collective of deities and praeterhuman intelligences central to Aleister Crowley''s Thelema as set out in Liber AL vel Legis (1904) and its surrounding corpus.'),
 ('ENT_THL_HOOR_PAAR_KRAAT','Hoor-paar-kraat','Thelemic','Thelemic deity','Deity','silence; the inmost; passivity; secrecy','B','The silent passive twin of Ra-Hoor-Khuit, the god of silence; a Thelemic adaptation of Harpocrates forming a polarity with the active conquering child.'),
 ('ENT_THL_BABALON','Babalon','Thelemic','Thelemic deity','Deity','the Great Mother; ecstasy; the Scarlet Woman; liberation; the Abyss','B','The Thelemic Great Mother and sacred-whore goddess riding the Beast, developed by Crowley (notably in The Vision and the Voice) as a redemptive reframing of the biblical Whore of Babylon.'),
 ('ENT_THL_THERION','Therion (The Beast 666)','Thelemic','Thelemic deity','Deity','force; the magical self; prophecy; consort of Babalon','B','To Mega Therion, ''The Great Beast 666,'' Crowley''s prophetic magical office and consort of Babalon; an affirmative reclamation of the apocalyptic Beast of Revelation.'),
 ('ENT_THL_CHORONZON','Choronzon','Thelemic','Praeterhuman intelligence','Demon','the Abyss; dispersion; chaos; dissolution of the ego','B','The demon and ''dweller in the Abyss'' encountered in the 10th Aethyr; first named in John Dee''s Enochian records and greatly developed by Crowley into the Thelemic embodiment of dispersion.'),
 ('ENT_THL_HGA','The Holy Guardian Angel','Thelemic','Concept','Concept','the true self; tutelary spirit; attainment; knowledge and conversation','B','The Thelemic/Abramelin concept of the individual''s tutelary genius or true higher self, whose ''Knowledge and Conversation'' is the central attainment; adopted from the Book of Abramelin and recast by Crowley, who identified Aiwass as his own HGA.'),
 ('ENT_THL_AEON_HORUS','The Aeon of Horus','Thelemic','Concept','Concept','the present age; the crowned and conquering child; self-realization','B','The current cosmic age inaugurated in 1904 according to Thelema, succeeding the Aeons of Isis and Osiris and governed by Ra-Hoor-Khuit; modeled as an era rather than a being.'),
 ('ENT_THE_HIERARCHY','The Theosophical Spiritual Hierarchy','Theosophical','Collective','Collective','the spiritual hierarchy of beings governing planetary and cosmic evolution','B','The graded hierarchy of spiritual beings — the Masters, the Lord of the World, the Logoi, and the Lords of Karma — said in Theosophy to oversee human and planetary evolution.'),
 ('ENT_THE_MORYA','Morya (Master M.)','Theosophical','Ascended master','Spirit','hidden wisdom; spiritual guidance; the first ray of will','B','Master Morya, one of the Mahatmas said to stand behind the Theosophical Society and to have corresponded with Blavatsky; a being original to the modern Theosophical movement.'),
 ('ENT_THE_KOOT_HOOMI','Koot Hoomi (Master K.H.)','Theosophical','Ascended master','Spirit','hidden wisdom; spiritual guidance; the second ray of love-wisdom','B','Master Koot Hoomi (Kuthumi), one of the principal Mahatmas of Theosophy and chief author of the Mahatma Letters; a being original to the modern Theosophical movement.'),
 ('ENT_THE_DJWAL_KHUL','Djwal Khul (The Tibetan)','Theosophical','Ascended master','Spirit','hidden wisdom; esoteric teaching; transmission','B','Master Djwal Khul, ''the Tibetan,'' a Mahatma later said to have telepathically dictated the books written through Alice Bailey; a being of the modern Theosophical tradition.'),
 ('ENT_THE_MAHA_CHOHAN','The Maha Chohan','Theosophical','Ascended master','Spirit','hidden wisdom; spiritual administration; the third ray','B','The ''Great Lord,'' chief of the third ray and head of the Masters'' hierarchy of civilization in Theosophical teaching; a being original to the modern Theosophical movement.'),
 ('ENT_THE_SANAT_KUMARA','Sanat Kumara','Theosophical','Cosmic being','Deity','the Lord of the World; Shamballa; planetary governance; the Ancient of Days','B','The ''Lord of the World'' and ''Ancient of Days'' said to dwell at Shamballa and govern Earth''s spiritual evolution; a Theosophical adaptation of the Hindu Kumara name into a modern cosmic office.'),
 ('ENT_THE_SOLAR_LOGOS','The Solar Logos','Theosophical','Cosmic being','Deity','the solar system; cosmic consciousness; the divine animating logos','B','The Theosophical conception of the divine intelligence ensouling and governing the entire solar system, developed within the modern revival from the Greek philosophical Logos.'),
 ('ENT_THE_PLANETARY_LOGOS','The Planetary Logos','Theosophical','Cosmic being','Deity','planetary governance; the Earth-chain; cosmic consciousness','B','The Theosophical divine intelligence ensouling a single planet, subordinate to the Solar Logos; a modern-revival cosmological office.'),
 ('ENT_THE_LIPIKA','The Lords of Karma (The Lipika)','Theosophical','Cosmic being','Collective','karma; the cosmic record; the law of cause and effect; the akashic record','B','The Lipika, the ''recorders'' or Lords of Karma described in Blavatsky''s The Secret Doctrine who register every act and administer the law of karma; a collective being of modern Theosophical cosmology.'),
 ('ENT_THE_ROOT_RACES','The Root Races','Theosophical','Cosmic being','Collective','human evolution; cosmic cycles; the seven humanities','B','The series of seven successive cosmological humanities (Lemurian, Atlantean, Aryan, ...) through which spirit evolves in The Secret Doctrine; modeled as a single collective rather than seven entities.'),
 ('ENT_MOD_GOLDEN_DAWN','The Hermetic Order of the Golden Dawn','Modern Occult','Magical order','Collective','ceremonial magic; initiation; the Western esoteric synthesis','B','The influential English initiatory magical order founded in 1888 that synthesized Qabalah, Enochian, Egyptian, and Tarot systems; a synthesizing framework rather than a source of new beings.'),
 ('ENT_MOD_SECRET_CHIEFS','The Secret Chiefs','Modern Occult','Praeterhuman intelligence','Collective','hidden authority; initiation; direction of the Order','B','The hidden Third-Order adepts said to direct the Hermetic Order of the Golden Dawn through its leaders (notably claimed by Mathers); a concept paralleling and influenced by the Theosophical Masters.');
