INSERT INTO _r VALUES
 ('ENT_THL_NUIT','member_of','ENT_THL_PANTHEON','high','Nuit is one of the principal deities of Liber AL vel Legis.'),
 ('ENT_THL_HADIT','member_of','ENT_THL_PANTHEON','high','Hadit is one of the principal deities of Liber AL vel Legis.'),
 ('ENT_THL_RA_HOOR_KHUIT','member_of','ENT_THL_PANTHEON','high','Ra-Hoor-Khuit is one of the principal deities of Liber AL vel Legis.'),
 ('ENT_THL_AIWASS','member_of','ENT_THL_PANTHEON','high','Aiwass, the intelligence who dictated Liber AL, is central to the Thelemic pantheon.'),
 ('ENT_THL_HOOR_PAAR_KRAAT','member_of','ENT_THL_PANTHEON','high','Hoor-paar-kraat is the silent twin within the Thelemic godhead.'),
 ('ENT_THL_BABALON','member_of','ENT_THL_PANTHEON','high','Babalon is a central deity of the Thelemic corpus.'),
 ('ENT_THL_THERION','member_of','ENT_THL_PANTHEON','high','Therion/The Beast 666 is a central figure of the Thelemic corpus.'),
 ('ENT_THL_CHORONZON','member_of','ENT_THL_PANTHEON','high','Choronzon is the Thelemic demon of the Abyss within the system.'),
 ('ENT_THL_HOOR_PAAR_KRAAT','reception_of','ENT_SYN_HARPOCRATES','high','Hoor-paar-kraat is the Thelemic form of the Greco-Egyptian Harpocrates.'),
 ('ENT_THL_BABALON','reception_of','ENT_CHR_WHORE_BABYLON','high','Babalon is Crowley''s reframing of the biblical Whore of Babylon.'),
 ('ENT_THL_THERION','reception_of','ENT_CHR_BEAST','high','Therion/The Beast 666 is Crowley''s reclamation of the apocalyptic Beast of Revelation.'),
 ('ENT_THL_CHORONZON','reception_of','ENT_REN_ENOCHIAN','high','Choronzon was first named in John Dee''s Enochian records and later developed by Crowley.'),
 ('ENT_THL_BABALON','consort_of','ENT_THL_THERION','high','Babalon and Therion (the Beast) are the paired feminine and masculine principles of the new aeon.'),
 ('ENT_THL_HOOR_PAAR_KRAAT','paired_with','ENT_THL_RA_HOOR_KHUIT','high','Hoor-paar-kraat is the silent passive twin of the active Ra-Hoor-Khuit, two aspects of Heru-ra-ha.'),
 ('ENT_THL_RA_HOOR_KHUIT','presides_over','ENT_WAR','high','Ra-Hoor-Khuit is the warlike crowned-and-conquering lord of force and vengeance.'),
 ('ENT_THL_THERION','presides_over','ENT_MAGIC','medium','Therion is Crowley''s prophetic magical office central to the practice of magick.'),
 ('ENT_THL_CHORONZON','presides_over','ENT_DESTRUCTION','medium','Choronzon is the power of dispersion and dissolution at the Abyss.'),
 ('ENT_THL_AIWASS','presides_over','ENT_REVELATION','high','Aiwass is the intelligence who delivered the revelation of Liber AL.'),
 ('ENT_THL_AIWASS','aligned_with','ENT_THL_HGA','medium','Crowley identified Aiwass as his own Holy Guardian Angel.'),
 ('ENT_THL_RA_HOOR_KHUIT','rules','ENT_THL_AEON_HORUS','high','Ra-Hoor-Khuit is the lord governing the Aeon of Horus.'),
 ('ENT_THE_MORYA','member_of','ENT_REC_MAHATMAS','high','Morya is one of the Mahatmas (Theosophical Masters of Wisdom).'),
 ('ENT_THE_KOOT_HOOMI','member_of','ENT_REC_MAHATMAS','high','Koot Hoomi is one of the Mahatmas.'),
 ('ENT_THE_DJWAL_KHUL','member_of','ENT_REC_MAHATMAS','high','Djwal Khul is one of the Mahatmas.'),
 ('ENT_THE_MAHA_CHOHAN','member_of','ENT_REC_MAHATMAS','high','The Maha Chohan heads a department within the Mahatmas'' hierarchy.'),
 ('ENT_REC_MAHATMAS','member_of','ENT_THE_HIERARCHY','high','The Mahatmas form the human-adept tier of the Theosophical Spiritual Hierarchy.'),
 ('ENT_THE_SANAT_KUMARA','member_of','ENT_THE_HIERARCHY','high','Sanat Kumara, the Lord of the World, heads the Theosophical Spiritual Hierarchy.'),
 ('ENT_THE_SOLAR_LOGOS','member_of','ENT_THE_HIERARCHY','high','The Solar Logos stands at the cosmic apex of the Theosophical hierarchy.'),
 ('ENT_THE_PLANETARY_LOGOS','member_of','ENT_THE_HIERARCHY','high','The Planetary Logos governs Earth within the hierarchy, subordinate to the Solar Logos.'),
 ('ENT_THE_LIPIKA','member_of','ENT_THE_HIERARCHY','high','The Lords of Karma administer the law of karma within the cosmic hierarchy.'),
 ('ENT_THE_ROOT_RACES','member_of','ENT_THE_HIERARCHY','medium','The Root Races are the evolving humanities overseen by the Spiritual Hierarchy.'),
 ('ENT_THE_SANAT_KUMARA','presides_over','ENT_HIDDEN_KNOWLEDGE','medium','As Lord of the World at Shamballa, Sanat Kumara governs the spiritual evolution overseen by the hidden hierarchy.'),
 ('ENT_REC_MAHATMAS','presides_over','ENT_HIDDEN_KNOWLEDGE','high','The Masters of the Ancient Wisdom are the custodians of hidden wisdom in Theosophy.'),
 ('ENT_THE_LIPIKA','presides_over','ENT_DEATH','low','The Lords of Karma administer the cycle of death and rebirth, though their domain is karma broadly.'),
 ('ENT_MOD_SECRET_CHIEFS','member_of','ENT_MOD_GOLDEN_DAWN','high','The Secret Chiefs are the hidden Third Order said to direct the Golden Dawn.'),
 ('ENT_MOD_GOLDEN_DAWN','presides_over','ENT_MAGIC','high','The Golden Dawn was the foremost order of ceremonial magic in the modern revival.'),
 ('ENT_MOD_SECRET_CHIEFS','presides_over','ENT_HIDDEN_KNOWLEDGE','medium','The Secret Chiefs are the hidden source of authority and knowledge directing the Golden Dawn.'),
 ('ENT_MOD_GOLDEN_DAWN','reception_of','ENT_REN_ENOCHIAN','high','The Golden Dawn incorporated John Dee''s Enochian system into its synthesis.'),
 ('ENT_MOD_SECRET_CHIEFS','aligned_with','ENT_REC_MAHATMAS','medium','The Secret Chiefs parallel and were influenced by the Theosophical Masters.');
